BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email) VALUES('00000000-0000-4000-a097-000000000001','sms-owner@example.test');
INSERT INTO businesses(id,owner_id,name,business_type,slug,billing_mode,partner_plan,telnyx_messaging_profile_id,telnyx_campaign_id,campaign_status)
VALUES('10000000-0000-4000-a097-000000000001','00000000-0000-4000-a097-000000000001','SMS Test','general','sms-097','comped','sms_and_chat','profile-097','campaign-097','approved');
INSERT INTO phone_numbers(id,business_id,phone_number,telnyx_phone_number_id,is_active,telnyx_campaign_assignment_status,telnyx_campaign_assignment_campaign_id)
VALUES('20000000-0000-4000-a097-000000000001','10000000-0000-4000-a097-000000000001','+15555550971','phone_097',true,'assigned','campaign-097');
INSERT INTO billing_usage_periods(id,business_id,period_start,period_end,plan,included_sms_parts)
VALUES('30000000-0000-4000-a097-000000000001','10000000-0000-4000-a097-000000000001',date_trunc('month',now()),date_trunc('month',now())+interval '1 month','sms_and_chat',2);
INSERT INTO contacts(id,business_id,phone_number,source_channel) VALUES('40000000-0000-4000-a097-000000000001','10000000-0000-4000-a097-000000000001','+15555550972','sms');
INSERT INTO conversations(id,business_id,contact_id,channel,is_ai_handling) VALUES('50000000-0000-4000-a097-000000000001','10000000-0000-4000-a097-000000000001','40000000-0000-4000-a097-000000000001','sms',false);
CREATE FUNCTION pg_temp.sms_reserve(p_key text,p_parts integer DEFAULT 1,p_purpose text DEFAULT 'manual_dashboard_send',p_fingerprint text DEFAULT 'fingerprint') RETURNS jsonb LANGUAGE sql AS $$
 SELECT reserve_tenant_sms('10000000-0000-4000-a097-000000000001','30000000-0000-4000-a097-000000000001',p_key,p_fingerprint,p_purpose,'profile-097','+15555550971','+15555550972',p_parts,'50000000-0000-4000-a097-000000000001');
$$;
CREATE TEMP TABLE sms_test_ids(key text PRIMARY KEY,id uuid);
INSERT INTO sms_test_ids VALUES('a',(pg_temp.sms_reserve('request-a',2)->'reservation'->>'id')::uuid);
SELECT throws_ok($$SELECT pg_temp.sms_reserve('request-b')$$,'P0001','sms_usage_limit_reached','pending reservation consumes capacity before provider acceptance');
SELECT is(pg_temp.sms_reserve('request-a',2)->>'send','false','same request cannot cross provider twice');
SELECT throws_ok($$SELECT pg_temp.sms_reserve('request-a',2,'manual_dashboard_send','changed')$$,'P0001','sms_idempotency_conflict','reused key cannot change content');
SELECT settle_tenant_sms((SELECT id FROM sms_test_ids WHERE key='a'),'uncertain');
SELECT throws_ok($$SELECT pg_temp.sms_reserve('request-c')$$,'P0001','sms_usage_limit_reached','uncertain acceptance continues holding quota');
SELECT settle_tenant_sms((SELECT id FROM sms_test_ids WHERE key='a'),'accepted','provider-097-a',p_delivery_status=>'delivered');
SELECT is((SELECT outbound_sms_parts FROM billing_usage_periods WHERE id='30000000-0000-4000-a097-000000000001'),2,'acceptance records parts atomically');
SELECT settle_tenant_sms((SELECT id FROM sms_test_ids WHERE key='a'),'accepted','provider-097-a',p_delivery_status=>'sent');
SELECT is((SELECT delivery_status FROM tenant_sms_sends WHERE id=(SELECT id FROM sms_test_ids WHERE key='a')),'delivered','reordered receipt cannot regress final delivery');
SELECT is(record_billing_usage_event('10000000-0000-4000-a097-000000000001','30000000-0000-4000-a097-000000000001','legacy-bookkeeping','outbound','sms','legacy',2,0,'provider-097-a','{}'),false,'legacy bookkeeping for accepted provider message cannot bill twice');
SELECT is((SELECT outbound_sms_parts FROM billing_usage_periods WHERE id='30000000-0000-4000-a097-000000000001'),2,'duplicate acceptance preserves usage');
UPDATE billing_usage_periods SET included_sms_parts=4 WHERE id='30000000-0000-4000-a097-000000000001';
INSERT INTO sms_test_ids VALUES('rejected',(pg_temp.sms_reserve('request-rejected',2)->'reservation'->>'id')::uuid);
SELECT settle_tenant_sms((SELECT id FROM sms_test_ids WHERE key='rejected'),'not_sent',p_reason=>'provider_rejected');
SELECT lives_ok($$SELECT pg_temp.sms_reserve('request-after-rejection',1)$$,'definite provider rejection frees reserved capacity');
SELECT ok(NOT has_function_privilege('authenticated','public.reserve_tenant_sms(uuid,uuid,text,text,text,text,text,text,integer,uuid,uuid)','EXECUTE'),'owner cannot reserve arbitrary SMS via RPC');
SELECT ok(NOT has_table_privilege('authenticated','public.tenant_sms_suppressions','DELETE'),'owner cannot clear STOP through direct writes');
SELECT is(tenant_sms_inbound('10000000-0000-4000-a097-000000000001','profile-097','+15555550972','STOP','50000000-0000-4000-a097-000000000001')->>'keyword','stop','STOP is recorded synchronously');
SELECT throws_ok($$SELECT pg_temp.sms_reserve('after-stop')$$,'P0001','sms_recipient_opted_out','STOP blocks normal manual messages');
SELECT tenant_sms_inbound('10000000-0000-4000-a097-000000000001','profile-097','+15555550972','START','50000000-0000-4000-a097-000000000001');
SELECT is((SELECT count(*)::integer FROM tenant_sms_suppressions),0,'START clears local carrier suppression only');
INSERT INTO tenant_sms_human_holds(business_id,messaging_profile_id,destination,conversation_id) VALUES('10000000-0000-4000-a097-000000000001','profile-097','+15555550972','50000000-0000-4000-a097-000000000001');
SELECT throws_ok($$SELECT pg_temp.sms_reserve('held-ai',1,'ai_reply')$$,'P0001','sms_review_human_hold','review hold stops AI at send boundary');
SELECT throws_ok($$UPDATE conversations SET is_ai_handling=true WHERE id='50000000-0000-4000-a097-000000000001'$$,'P0001','sms_review_human_hold','service code cannot silently resume held AI');
SELECT is(tenant_sms_inbound('10000000-0000-4000-a097-000000000001','profile-097','+15555550972','Thanks','50000000-0000-4000-a097-000000000001')->>'reviewHeld','true','review reply remains in human inbox');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-a097-000000000001',true);
SELECT set_config('request.jwt.claim.role','authenticated',true);
SELECT lives_ok($$UPDATE conversations SET is_ai_handling=true,status='active' WHERE id='50000000-0000-4000-a097-000000000001'$$,'entitled owner may explicitly resume AI');
RESET ROLE;
SELECT set_config('request.jwt.claim.role','service_role',true);
SELECT ok((SELECT released_at IS NOT NULL FROM tenant_sms_human_holds WHERE business_id='10000000-0000-4000-a097-000000000001'),'owner resume releases review human hold');
UPDATE businesses SET partner_plan='chat_only' WHERE id='10000000-0000-4000-a097-000000000001';
UPDATE tenant_sms_human_holds SET released_at=NULL;
UPDATE conversations SET is_ai_handling=false WHERE id='50000000-0000-4000-a097-000000000001';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',true);
SELECT throws_ok($$UPDATE conversations SET is_ai_handling=true WHERE id='50000000-0000-4000-a097-000000000001'$$,'P0001','sms_review_human_hold','Chat owner cannot gain AI by resuming a review conversation');
RESET ROLE;
UPDATE businesses SET owner_id=NULL WHERE id='10000000-0000-4000-a097-000000000001';
SELECT is((SELECT count(*)::integer FROM tenant_sms_sends),0,'tombstone cleanup removes message routing PII');
SELECT * FROM finish();
ROLLBACK;
